using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.Controls;
using IDS.Core;

namespace IDS.XR
{
    /// <summary>
    /// Drives the camera from the headset's centre-eye pose.
    ///
    /// WHY NOT TrackedPoseDriver. TrackedPoseDriver does exactly this, but it
    /// reads its pose through serialized InputActionProperty fields — each one an
    /// embedded InputAction with its own id, expected control type and binding
    /// path. A scene generated by script has to construct all of that through
    /// SerializedProperty, and when any part of it is wrong the component
    /// silently does nothing: the camera stays bolted to the seat and the whole
    /// headset feels broken with no error anywhere. Reading the pose in code is
    /// four lines against control names verified from the Input System package
    /// itself, and it logs when it cannot find the device.
    ///
    /// WHY NOT RELY ON THE ENGINE. Unity's XR integration does apply the head
    /// pose to a stereo camera on its own (hence XRDevice.DisableAutoXRCameraTracking),
    /// but XROrigin warns when no pose driver is present and Unity's own
    /// documentation treats a driver as required. Depending on undocumented
    /// default behaviour for the single most important transform in the
    /// application is not a trade worth making.
    ///
    /// TIMING. The pose is applied in Update and again on Application.onBeforeRender,
    /// which is what TrackedPoseDriver does. The second application is what keeps
    /// head motion from lagging a frame behind the render — without it the whole
    /// world swims when the driver turns their head, which is both unpleasant and
    /// a genuine comfort risk.
    ///
    /// This writes the camera's LOCAL pose, so the camera must be a child of the
    /// XR Origin's Camera Offset object: the pose is in tracking space, which is
    /// what that transform represents.
    /// </summary>
    public class XRHeadAnchor : MonoBehaviour
    {
        [Tooltip("Logs the head pose periodically. Leave on until a session has " +
                 "been verified on the headset — a dead tracking path is otherwise " +
                 "indistinguishable from a driver sitting very still.")]
        [SerializeField] private bool logPose = true;

        [SerializeField] private float logInterval = 5f;

        /// <summary>True once a head pose has been read at least once.</summary>
        public bool HasPose { get; private set; }

        private InputDevice _hmd;
        private Vector3Control _position;
        private QuaternionControl _rotation;
        private ButtonControl _isTracked;

        private float _nextLog;
        private float _nextScan;
        private bool _warned;

        private void Awake() => ServiceRegistry.Register(this);

        private void OnEnable() => Application.onBeforeRender += ApplyPose;
        private void OnDisable() => Application.onBeforeRender -= ApplyPose;

        private void Update()
        {
            ApplyPose();

            if (!logPose || Time.unscaledTime < _nextLog) return;
            _nextLog = Time.unscaledTime + logInterval;

            Debug.Log(HasPose
                ? $"[Head] local pos={transform.localPosition} " +
                  $"euler={transform.localEulerAngles} tracked={IsTracked()}"
                : "[Head] no HMD pose yet — the camera is not being driven. In the " +
                  "editor without a headset this is expected.");
        }

        private void ApplyPose()
        {
            if (!Resolve()) return;

            if (_position != null) transform.localPosition = _position.ReadValue();
            if (_rotation != null) transform.localRotation = _rotation.ReadValue();

            HasPose = true;
        }

        private bool IsTracked() => _isTracked == null || _isTracked.isPressed;

        /// <summary>
        /// Finds the HMD and caches its controls. Re-scans at most once a second
        /// while it is absent, so a headset that wakes up late is picked up
        /// without scanning the device list every frame.
        /// </summary>
        private bool Resolve()
        {
            if (_hmd != null && _hmd.added) return true;

            if (Time.unscaledTime < _nextScan) return false;
            _nextScan = Time.unscaledTime + 1f;

            _hmd = null;
            _position = null;
            _rotation = null;
            _isTracked = null;

            foreach (InputDevice d in InputSystem.devices)
            {
                if (!d.added) continue;

                // Matched by the controls it exposes rather than by layout name:
                // which concrete layout an OpenXR runtime registers for the
                // headset varies, but anything that is an HMD has a centre eye.
                var pos = d.TryGetChildControl<Vector3Control>("centerEyePosition");
                if (pos == null) continue;

                _hmd = d;
                _position = pos;
                _rotation = d.TryGetChildControl<QuaternionControl>("centerEyeRotation");
                _isTracked = d.TryGetChildControl<ButtonControl>("isTracked");
                break;
            }

            if (_hmd != null)
            {
                Debug.Log($"[Head] driving the camera from '{_hmd.displayName}' " +
                          $"(layout {_hmd.layout}); rotation control " +
                          $"{(_rotation != null ? "found" : "MISSING")}");
                _warned = false;
                return true;
            }

            if (_warned) return false;
            _warned = true;

            var sb = new System.Text.StringBuilder(
                "[Head] no device exposing centerEyePosition. The camera will not " +
                "follow the headset. Devices present:\n");
            foreach (InputDevice d in InputSystem.devices)
                sb.AppendLine($"   {d.displayName} (layout {d.layout})");
            Debug.LogWarning(sb.ToString());

            return false;
        }
    }
}
